# port scan plugin
yakit.AutoInitYakit()

/*
本插件定义的函数主要用于端口扫描的额外扩展

函数定义如下：
func(result *fp.MatchResult)

// 详细结构体定义与内容见模版结尾
// 这里最关键的是，如果对扫描出的结果有疑问，需要对 MatchResult 进行修改，应该直接
// 对变量.Field 进行修改。

DEMO:

handle = func(result) {
    if result.Fingerprint != nil {
        if result.Port == 80 && result.GetServiceName() == "" {
            result.Fingerprint.ServiceName = "http"
        }
    }
}

*/
Handshake = []uint8{74, 68, 87, 80, 45, 72, 97, 110, 100, 115, 104, 97, 107, 101} #握手
cmd = []uint8{0,0,0,11,0,0,0,9,0,1,1}  #获取jdwp版本信息

#发送数据
send = func(tcp,data){
   datalen, err = tcp.Write(data)
   if err != nil{
       yakit.Info("发送失败！")
       return false
   }
   return true
}
#接收数据
receive = func(tcp,data){
    datalen, err = tcp.Read(data)
    if err != nil{
       yakit.Info("接受失败！")
       return false
   }
   return true

}

#检测漏洞
handleCheck = func(target, port){
    jdwptcp,err  = tcp.Connect(target,port)
    if err != nil{
        return
    }

    raddr = jdwptcp.RemoteAddr().String()
    brsp = make([]uint8,14,14)
    send(jdwptcp,Handshake)
    receive(jdwptcp, brsp)

    if string(brsp)  == string(Handshake){
        yakit.Info("发现jdwp指纹！")
        yakit.Info("获取版本信息！")
        versionrsp = make([]uint8,230,230)
        send(jdwptcp,cmd)
        receive(jdwptcp,versionrsp)
        risk.NewRisk(
            raddr,
            risk.type("rce"),
            risk.level("high"),
            risk.token(brsp),
            risk.payload(Handshake),
            // risk.title("Java Debug 远程调试接口远程代码执行漏洞target: %v"%target),
            risk.titleVerbose("Java Debug 远程调试接口远程代码执行漏洞target: %v"%target),
            risk.details({
                    "request":Handshake,
                    "response":versionrsp[11:],
                    "port":port,
                    }),
        )
    }

}

handle = func(result /* *fp.MatchResult */) {
    if !result.IsOpen(){
        return
    }
    if len(result.Fingerprint.HttpFlows) == 0{
        handleCheck(result.Target,result.Port)
    }

}

/*
// 具体定义如下：
type palm/common/fp.(MatchResult) struct {
      Target: string  
      Port: int  
      State: fp.PortState  
      Reason: string  
      Fingerprint: *fp.FingerprintInfo  
  StructMethods(结构方法/函数): 
  PtrStructMethods(指针结构方法/函数): 
      func GetBanner() return(string) 
      func GetCPEs() return([]string) 
      func GetDomains() return([]string) 
      func GetHtmlTitle() return(string) 
      func GetProto() return(fp.TransportProto) 
      func GetServiceName() return(string) 
      func IsOpen() return(bool) 
      func String() return(string) 
}


type palm/common/fp.(FingerprintInfo) struct {
      IP: string  
      Port: int  
      Proto: fp.TransportProto  
      ServiceName: string  
      ProductVerbose: string  
      Info: string  
      Version: string  
      Hostname: string  
      OperationVerbose: string  
      DeviceType: string  
      CPEs: []string  
      Raw: string  
      Banner: string  
      CPEFromUrls: map[string][]*webfingerprint.CPE  
      HttpFlows: []*fp.HTTPFlow  
  StructMethods(结构方法/函数): 
  PtrStructMethods(指针结构方法/函数): 
      func FromRegexp2Match(v1: *regexp2.Match) 
}
*/
